-- Painel SST — dados de demonstração (fictícios). Gerado por gerar_seed.py.
set search_path = pn, pn_crm, public;
truncate pn_crm.notificacao, pn_crm.chat_mensagem, pn_crm.chat_membro, pn_crm.wa_historico_msg, pn_crm.wa_historico_conversa, pn_crm.wa_contato, pn_crm.atestado_alerta, pn_crm.atestado, pn_crm.agendamento_evento, pn_crm.agendamento, pn_crm.agenda, pn_crm.tarefa_comentario, pn_crm.tarefa_item, pn_crm.tarefa, pn_crm.cobranca_evento, pn_crm.cobranca, pn_crm.contrato_evento, pn_crm.contrato_item, pn_crm.contrato, pn_crm.evento, pn_crm.negocio_item, pn_crm.negocio, pn_crm.rodizio, pn_crm.rodizio_estado, pn_crm.empresa_interacao, pn_crm.edicao cascade;
truncate pn.atendimento_exame, pn.atendimento, pn.colaborador_vinculo, pn.colaborador, pn.funcao_exame, pn.pcmso_exame_funcao, pn.funcao, pn.setor, pn.documento, pn.unidade, pn.empresa_contato, pn.empresa, pn.profissional, pn.exame_tipo cascade;
-- perfis da equipe (os logins são criados em pn_04_usuarios.sql)
delete from pn_crm.pre_cadastro;
delete from pn_crm.admin_inicial;
update pn_crm.produto set preco = round((80 + random() * 900)::numeric, -1) where preco is not null;

-- histórico de ASO gerado no banco: admissional + periódicos pela periodicidade da função; ~22% param de fazer (vencidos)
select setseed(0.26);
drop table if exists _c; create temp table _c as
select c.id, c.empresa_id, c.unidade_id, c.funcao_id, c.data_admissao adm, coalesce(c.data_demissao, current_date) fim, c.data_demissao dem,
       coalesce((select min(fe.periodicidade_meses) from pn.funcao_exame fe where fe.funcao_id = c.funcao_id), 12) meses,
       case when random() < .22 then current_date - (random() * 500)::int end parar
  from pn.colaborador c;
                             situacao, aso_resultado, aso_emitido_em, local_atendimento, origem)
select c.empresa_id, c.unidade_id, c.id, c.funcao_id, (array['4c8b326e-a6ac-5a04-b126-e90d366b44b1'::uuid,'c53661ea-cee0-5e60-af6b-42cdd1b01a73'::uuid,'6fb2e78c-e707-53b1-9439-ea8b4f228e72'::uuid])[1 + floor(random() * 3)::int],
       (case when g.n = 0 then 'admissional' else 'periodico' end)::pn.tipo_exame_ocupacional,
       (x.d + time '08:00' + (floor(random() * 16) * interval '30 minutes')), x.d, 'finalizado',
       (case when random() < .95 then 'apto' when random() < .8 then 'apto_com_restricao' else 'inapto' end)::pn.resultado_aso, x.d, 'clinica', 'manual'
  from _c c cross join lateral generate_series(0, 40) g(n)
  cross join lateral (select case when g.n = 0 then c.adm
                             else (c.adm + make_interval(months => g.n * c.meses) + ((floor(random() * 45) - 20)::int * interval '1 day'))::date end d) x
 where x.d <= c.fim and (g.n = 0 or c.parar is null or x.d <= c.parar);
                             situacao, aso_resultado, aso_emitido_em, local_atendimento, origem)
select c.empresa_id, c.unidade_id, c.id, c.funcao_id, (array['4c8b326e-a6ac-5a04-b126-e90d366b44b1'::uuid,'c53661ea-cee0-5e60-af6b-42cdd1b01a73'::uuid,'6fb2e78c-e707-53b1-9439-ea8b4f228e72'::uuid])[1], 'demissional', c.dem + time '10:00', c.dem, 'finalizado', 'apto', c.dem, 'clinica', 'manual'
  from _c c where c.dem is not null;
select a.id, fe.exame_tipo_id, a.data_atendimento, (case when random() < .93 then 'normal' else 'alterado' end)::pn.resultado_exame
  from pn.atendimento a join pn.funcao_exame fe on fe.funcao_id = a.funcao_id
 where (a.tipo = 'demissional' and fe.exame_nome = 'Exame Clínico') or (a.tipo <> 'demissional' and (a.tipo = 'admissional' or random() < .9));
