alter table pn_crm.negocio enable trigger negocio_do_comercial;

update pn_crm.contrato c set status = 'assinado', inicio = (n.fechado_em at time zone 'America/Sao_Paulo')::date,
       fim = (n.fechado_em at time zone 'America/Sao_Paulo')::date + interval '12 months',
       assinado_em = n.fechado_em + interval '3 days', prazo_meses = 12, valor_mensal = round(c.valor_total / 12, 2),
       representante_legal = n.contato_nome, email_notificacao = n.contato_email
  from pn_crm.negocio n where n.id = c.negocio_id;
select c.empresa_id, c.cliente_nome, c.id, 'Mensalidade ' || to_char(m, 'MM/YYYY') || ' — ' || c.titulo, m::date,
       (m + interval '4 days')::date, greatest(c.valor_mensal, 150),
       case when (m + interval '4 days')::date < current_date and random() < .88 then greatest(c.valor_mensal, 150) end,
       case when (m + interval '4 days')::date < current_date then (m + interval '4 days' + (random() * 6 || ' days')::interval)::date end,
       'boleto', 'contrato'
  from pn_crm.contrato c
  cross join lateral generate_series(date_trunc('month', c.inicio), least(date_trunc('month', c.fim), date_trunc('month', current_date)), interval '1 month') m
 where c.status = 'assinado';
update pn_crm.cobranca set pago_em = null where valor_pago is null;
update pn_crm.wa_config set inbox_url = 'https://painel.exemplo.com.br/inbox';
select pn_app.recalcular_vencimentos();
select setval(pg_get_serial_sequence('pn_crm.negocio', 'numero'), (select max(numero) from pn_crm.negocio)) where exists (select 1 from pn_crm.negocio);
